import torch
from liger_kernel.ops.group_norm import LigerGroupNormFunction


@torch.no_grad()
def run(x, weight, bias, eps):
    # LigerGroupNormFunction.apply expects:
    # (X, affine_scaling_weight, affine_shifting_bias, num_channels, num_groups, eps)
    # x shape: (N, C, H, W), weight: (C,), bias: (C,)
    N, C = x.shape[0], x.shape[1]
    # Determine num_groups from the reference usage (default: num_groups=32)
    num_groups = 32
    if C % num_groups != 0:
        for g in [32, 16, 8, 4, 2, 1]:
            if C % g == 0:
                num_groups = g
                break
    return LigerGroupNormFunction.apply(x, weight, bias, C, num_groups, eps)
